// Decision cautions do not change RIASEC scores or remove sensible work options.
export function educationTradeoff(s,o){const choices=s.profileJourney?.answers?.education||[],level=o?.finance?.credentialLevel;if(choices.includes('training')&&!choices.some(x=>['college','graduate','unknown'].includes(x))&&['bachelor','graduate'].includes(level))return 'This job usually needs a degree. You chose a shorter training route.';if(level==='graduate'&&choices.length&&!choices.some(x=>['graduate','unknown'].includes(x)))return 'This job needs study after college. Allow for the extra time and cost.';return '';}
export function careerScopeNotes(id){return ({hairdresser:['Makeup interest alone does not establish a wish to cut or color hair. Compare the actual services before choosing a training route.'],animation:['Photography, editing and animation share creative tasks. Interest in images alone does not settle which medium you want to work in.'], 'biological-technician':['General biology laboratory work is a starting option. Forensic evidence work is a separate specialty, with its own duties and preparation.'],'farmworker-crops':['Commercial growing includes repeated physical and outdoor work. Enjoying plants at home does not establish an interest in that workday.'],'landscaping-worker':['Landscaping involves regular outdoor, physical work. Compare that workday with your interest in plants.']})[id]||[];}
export function careerTrial(id){return ({'biological-technician':'Ask a science teacher to use a prepared example or published data. Record observations, compare two samples, and explain what the evidence cannot tell you.',hairdresser:'Sketch two hair ideas for a pretend client. Compare that with a makeup design brief. Notice which work you want to repeat; no cutting or treatment is needed.','industrial-design':'Make a paper model of a useful object. Ask for feedback, change one feature, and notice whether you enjoy improving it.',animation:'Try a short moving-image sketch, then compare it with a three-photo story. Notice whether movement, selecting images, or telling the story interests you most.','film-editing':'Arrange a few existing clips into a short scene. Change the order and timing, and compare how the story feels.',photographer:'Make a three-photo story with a phone or borrowed camera. Choose the images and explain what each adds.'})[id]||null;}
